CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT UNIQUE NOT NULL, password_hash TEXT, name TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'student' CHECK(role IN ('admin','student','reviewer')), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tasks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title TEXT NOT NULL, track TEXT NOT NULL DEFAULT 'preliminary', description TEXT NOT NULL, deadline TIMESTAMPTZ NOT NULL, points INTEGER NOT NULL CHECK(points > 0), status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed')), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS submissions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, file_name TEXT NOT NULL, file_path TEXT NOT NULL, grade INTEGER CHECK(grade >= 0), feedback TEXT, submitted_at TIMESTAMPTZ DEFAULT NOW(), graded_at TIMESTAMPTZ, UNIQUE(task_id,user_id));
